<script setup lang="ts">
import { newRequestId } from '../domain/requestId'
import { computed } from 'vue'
import type { GameSession, Coordinate, GameAction, BonusType } from '../api/types'
const props = defineProps<{ session: GameSession; busy: boolean; fakeMode: boolean; fakePoint: Coordinate | null }>()
const emit = defineEmits<{ action: [action: GameAction]; chooseFake: []; cancelFake: [] }>()
const me = computed(() => props.session.participants.find(p => p.id === props.session.me))
const bonus = computed(() => me.value?.bonuses)
const allowed = computed(() => props.session.status === 'running' && me.value?.state === 'active')
const names: Record<BonusType, string> = { hunter_locations: 'Jägerpositionen', regeneration: 'Regeneration', fake_ping: 'Fake-Ping' }
function use(path: string, body: Record<string, unknown> = {}) { emit('action', { path: `/play/bonuses/${path}`, body: { ...body, requestId: newRequestId() } }) }
function time(value: string) { return new Date(value).toLocaleTimeString('de-DE') }
</script>
<template><section v-if="me?.role === 'runner' && bonus" class="panel runner-bonuses"><h2>Deine Boni</h2><article v-if="session.rules.topUpStationEnabled" class="bonus-card"><h3>Top Up Station</h3><p>5 Minuten im gelben 25-m-Kreis füllen deine Boni auf. Beim Betreten wird dein echter Standort einmalig an die Jäger gesendet. Beim Verlassen oder mehr als 30 Sekunden ohne Standortmeldung beginnt die Wartezeit neu.</p><p v-if="bonus.topUp" role="status">{{ bonus.topUp.refilledAt ? 'Boni aufgefüllt. Verlasse die Station, bevor du sie erneut nutzen kannst.' : `In der Station seit ${time(bonus.topUp.enteredAt)} · Auffüllung ab ${time(new Date(Date.parse(bonus.topUp.enteredAt) + 300000).toISOString())}` }}</p></article><p class="muted">Ab Spielstart verfügbar, auch während des Vorsprungs. Regeneration und Fake-Ping wirken ausschließlich auf Silent-Pings.</p><article class="bonus-card"><div><h3>Jägerpositionen erfragen <span class="badge">{{ bonus.remaining.hunter_locations }}</span></h3><p>Einmalige Momentaufnahme nur für dich. Keine laufende Standortverfolgung.</p></div><button :disabled="busy || !allowed || !bonus.remaining.hunter_locations" @click="use('hunter-locations')">Jägerpositionen erfragen</button><p v-if="session.hunterSnapshot" class="muted">Momentaufnahme von {{ time(session.hunterSnapshot.capturedAt) }} · rote Namensblasen auf der Karte.</p></article><article class="bonus-card"><div><h3>Regeneration <span class="badge">{{ bonus.remaining.regeneration }}</span></h3><p>Unterdrückt genau deinen nächsten Silent-Ping.</p></div><button class="secondary" :disabled="busy || !allowed || !bonus.remaining.regeneration || !!bonus.pending" @click="use('regeneration')">Regeneration aktivieren</button></article><article class="bonus-card"><div><h3>Fake-Ping <span class="badge">{{ bonus.remaining.fake_ping }}</span></h3><p>Ersetzt deinen nächsten Silent-Ping durch eine gewählte Position im Spielfeld.</p></div><div class="card-actions"><button class="secondary" :disabled="busy || !allowed || !bonus.remaining.fake_ping || !!bonus.pending" @click="emit('chooseFake')">{{ fakeMode ? 'Position auf der Karte wählen …' : 'Fake-Ping auf Karte wählen' }}</button><button v-if="fakePoint" :disabled="busy || !allowed || !!bonus.pending || !bonus.remaining.fake_ping" @click="use('fake-ping', { longitude: fakePoint[0], latitude: fakePoint[1] })">Fake-Ping aktivieren</button><button v-if="fakeMode || fakePoint" class="text-button" @click="emit('cancelFake')">Auswahl verwerfen</button></div><p v-if="fakePoint" class="muted">Gewählte Fake-Position: {{ fakePoint[1].toFixed(5) }}, {{ fakePoint[0].toFixed(5) }}</p></article><p v-if="bonus.pending" role="status" class="simulator-notice">{{ names[bonus.pending.type] }} vorgemerkt für {{ time(bonus.pending.scheduledAt) }}. Ein weiterer Silent-Bonus ist bis dahin gesperrt.</p><p v-else-if="bonus.lastAction" class="muted">Letzter Bonus: {{ names[bonus.lastAction.type] }} · {{ bonus.lastAction.status === 'expired' ? 'abgelaufen' : 'eingesetzt' }}</p></section></template>
